import { describe, expect, it, vi } from 'vitest';
import {
	DictionaryClient,
	FALLBACK_TIMEOUT_MS,
	normalizeFallback,
	normalizePrimary,
	PRIMARY_TIMEOUT_MS,
} from '../src/api/dictionary';
import { HttpError, HttpRequest } from '../src/api/types';
import serendipity from './fixtures/dictionary_entry.json';
import bass from './fixtures/dictionary_homographs.json';
import wiktionary from './fixtures/wiktionary_definition.json';

// Generated by the Python CLI's DictionaryClient from the same fixtures.
const CLI_SERENDIPITY =
	"---\ncollection: \"[[Lookups]]\"\ntags:\n  - noun\n---\n\n## Pronunciation\n/ˌsɛ.ɹən.ˈdɪ.pɪ.ti/\n\n## Noun\n1. A combination of events which have come together by chance to make a surprisingly good or wonderful outcome.\n2. An unsought, unintended, and/or unexpected, but fortunate, discovery and/or learning experience that happens by accident.\n   - *The discovery of penicillin was pure serendipity.*\n\n## Synonyms\n[[chance]], [[luck]]\n\n## Antonyms\n[[Murphy's law]], [[perfect storm]]\n\n## Source\nhttps://en.wiktionary.org/wiki/serendipity\nCC BY-SA 3.0\n";
const CLI_BASS_0 =
	'---\ncollection: "[[Lookups]]"\ntags:\n  - noun\n  - adjective\n---\n\n## Pronunciation\n/beɪs/\n\n## Noun\n1. A low spectrum of sound tones.\n\n## Adjective\n1. Of sound, a voice or an instrument, low in pitch or frequency.\n\n## Antonyms\n[[treble]]\n\n## Source\nhttps://en.wiktionary.org/wiki/bass\nCC BY-SA 3.0\n';
const CLI_BASS_1 =
	'---\ncollection: "[[Lookups]]"\ntags:\n  - noun\n---\n\n## Pronunciation\n/bæs/\n\n## Noun\n1. The perch; any of various marine and freshwater fish.\n\n## Source\nhttps://en.wiktionary.org/wiki/bass\nCC BY-SA 3.0\n';
const CLI_WIKTIONARY =
	'---\ncollection: "[[Lookups]]"\ntags:\n  - noun\n---\n\n## Noun\n1. The phenomenon of finding valuable things not sought for.\n   - *A fortunate stroke of serendipity.*\n2. An unsought, unintended or unexpected, but fortunate, discovery.\n\n## Source\nhttps://en.wiktionary.org/wiki/serendipity\nCC BY-SA 3.0\n';
const CLI_PHRASAL =
	'---\ncollection: "[[Lookups]]"\ntags:\n  - phrasal-verb\n---\n\n## Phrasal verb\n1. To leave.\n   - *The plane took off.*\n\n## Source\nhttps://en.wiktionary.org/wiki/take%20off\nCC BY-SA 3.0\n';

const notFound = () => new HttpError(404, 'Request failed with status 404');

function setup(...responses: unknown[]) {
	const request = vi.fn<(req: HttpRequest) => Promise<unknown>>();
	for (const r of responses) {
		if (r instanceof Error) request.mockRejectedValueOnce(r);
		else request.mockResolvedValueOnce(r);
	}
	return { client: new DictionaryClient(request, 'MediaNoteCreator/test'), request };
}

describe('DictionaryClient lookups', () => {
	it('asks the primary source with a short timeout and a User-Agent', async () => {
		const { client, request } = setup(serendipity);
		const results = await client.search('  serendipity ');
		expect(request.mock.calls[0]?.[0]).toEqual({
			url: 'https://api.dictionaryapi.dev/api/v2/entries/en/serendipity',
			headers: { 'User-Agent': 'MediaNoteCreator/test', Accept: 'application/json' },
			timeoutMs: PRIMARY_TIMEOUT_MS,
		});
		expect(results).toEqual([
			{
				id: 'serendipity#0',
				title: 'serendipity',
				year: null,
				overview:
					'[noun] A combination of events which have come together by chance to make a surprisingly good or wonderf...',
				thumbnailUrl: null,
			},
		]);
	});

	it('returns one entry per homograph', async () => {
		const { client } = setup(bass);
		const results = await client.search('bass');
		expect(results.map((r) => [r.id, r.overview])).toEqual([
			['bass#0', '[noun/adjective] A low spectrum of sound tones.'],
			['bass#1', '[noun] The perch; any of various marine and freshwater fish.'],
		]);
	});

	it('treats a 404 as an unknown word, without falling back', async () => {
		const { client, request } = setup(notFound(), serendipity);
		expect(await client.search('asdfgh')).toEqual([]);
		expect(request).toHaveBeenCalledTimes(1);
		await client.search('serendipity');
		expect(request.mock.calls[1]?.[0].url).toContain('dictionaryapi.dev');
	});

	it('falls back to Wiktionary on an error, then skips the primary for the rest of the batch', async () => {
		const { client, request } = setup(
			new HttpError(null, 'Network error: Timed out after 8 s'),
			wiktionary,
			wiktionary,
		);
		const first = await client.search('serendipity');
		expect(first).toHaveLength(1);
		expect(client.usingFallback).toBe(true);
		expect(request.mock.calls[1]?.[0]).toMatchObject({
			url: 'https://en.wiktionary.org/api/rest_v1/page/definition/serendipity',
			timeoutMs: FALLBACK_TIMEOUT_MS,
		});

		await client.search('serendipity');
		expect(request).toHaveBeenCalledTimes(3);
		expect(request.mock.calls[2]?.[0].url).toContain('wiktionary.org');
	});

	it('falls back on a 5xx too', async () => {
		const { client } = setup(new HttpError(503, 'status 503'), wiktionary);
		expect(await client.search('serendipity')).toHaveLength(1);
	});

	it('reports an error when both sources are down', async () => {
		const { client } = setup(new HttpError(500, 'status 500'), new HttpError(null, 'Network error'));
		await expect(client.search('serendipity')).rejects.toThrow('Dictionary API error: Network error');
	});

	it('handles the fallback having no English entry, or not knowing the word', async () => {
		const { client } = setup(new HttpError(500, 'x'), { fr: [] }, notFound());
		expect(await client.search('sérendipité')).toEqual([]);
		expect(await client.search('zzz')).toEqual([]);
	});

	it('ignores an empty word and a non-list response', async () => {
		const { client, request } = setup({ title: 'No Definitions Found' });
		expect(await client.search('   ')).toEqual([]);
		expect(request).not.toHaveBeenCalled();
		expect(await client.search('x')).toEqual([]);
	});

	it('serves details from the search cache, or looks the word up again', async () => {
		const { client, request } = setup(bass, bass);
		await client.search('bass');
		expect((await client.getDetails('bass#1')).phonetic).toBe('/bæs/');
		expect(request).toHaveBeenCalledTimes(1);

		const fresh = setup(bass).client;
		expect((await fresh.getDetails('bass#0')).phonetic).toBe('/beɪs/');
		const missing = setup(bass).client;
		await expect(missing.getDetails('bass#7')).rejects.toThrow('No dictionary entry');
	});
});

describe('DictionaryClient notes', () => {
	const { client } = setup();

	it('matches the CLI for the primary source', () => {
		expect(client.formatNote(normalizePrimary('serendipity', 0, serendipity[0]!))).toBe(CLI_SERENDIPITY);
		expect(client.formatNote(normalizePrimary('bass', 0, bass[0]!))).toBe(CLI_BASS_0);
		expect(client.formatNote(normalizePrimary('bass', 1, bass[1]!))).toBe(CLI_BASS_1);
	});

	it('matches the CLI for the Wiktionary fallback', () => {
		expect(client.formatNote(normalizeFallback('serendipity', wiktionary.en))).toBe(CLI_WIKTIONARY);
		const phrasal = normalizeFallback('take off', [
			{
				partOfSpeech: 'phrasal verb',
				definitions: [
					{ definition: 'To <i>leave</i>.', examples: ['', '<b>The plane</b> took off.'] },
					{ definition: '  ' },
				],
			},
			{ partOfSpeech: 'Noun', definitions: [] },
		]);
		expect(client.formatNote(phrasal)).toBe(CLI_PHRASAL);
		expect(client.getFilename(phrasal)).toBe('take off.md');
	});

	it('takes the pronunciation from phonetics when the top-level field is empty', () => {
		const entry = normalizePrimary('x', 0, { phonetic: ' ', phonetics: [{ text: '' }, { text: '/eks/' }] });
		expect(entry.phonetic).toBe('/eks/');
		expect(normalizePrimary('x', 0, {}).phonetic).toBeNull();
		expect(normalizePrimary('x', 0, {}).license).toBe('CC BY-SA 3.0');
	});

	it('names notes after the word, with no year and no poster', () => {
		const entry = normalizePrimary('what?', 0, { word: 'what?' });
		expect(client.getFilename(entry)).toBe('what.md');
		expect(client.getTitleAndYear(entry)).toEqual({ title: 'what?', year: null });
		expect(client.getPosterUrl()).toBeNull();
	});
});
